# ---------------------------------------------------------------- 配置 / 规则

def load_config(path=None):
    import yaml
    p = path or os.path.join(K.VAULT, CONFIG_REL)
    if not os.path.isfile(p):
        raise SystemExit(f"[!] 配置文件不存在: {p}")
    with open(p, "r", encoding="utf-8") as f:
        return yaml.safe_load(f) or {}


def norm_journal(s):
    """期刊名归一：小写、标点转空格、压空格。中英文都适用。"""
    s = str(s or "").strip().lower()
    s = re.sub(r"[^\w]+", " ", s, flags=re.UNICODE)
    return re.sub(r"\s+", " ", s).strip()


class JournalRules(object):
    """把卡里的 journal 字面值映射到白名单 tier。tier 只认 lit_config.yaml。"""

    def __init__(self, tiers, aliases=None):
        # tiers: {规范名: "T0".."T4"}
        self.tier = {}
        self.display = {}
        for name, tier in (tiers or {}).items():
            n = norm_journal(name)
            if n and tier:
                self.tier[n] = str(tier)
                self.display[n] = str(name)
        self.alias = {}
        self.bad_alias = []
        for canon, names in (aliases or {}).items():
            cn = norm_journal(canon)
            if cn not in self.tier:
                # 映射目标不在白名单：拒绝生效，并留证（否则等于偷偷造 tier）
                self.bad_alias.append(str(canon))
                continue
            for n in names or []:
                nn = norm_journal(n)
                if nn:
                    self.alias[nn] = cn

    def classify(self, journal):
        """返回 (kind, tier, canonical_norm)。

        kind: journal | preprint | non-journal | unranked | unknown
        """
        j = str(journal or "").strip()
        if not j:
            return ("unknown", None, None)
        nj = norm_journal(j)
        canon = self.alias.get(nj, nj)
        if canon in self.tier:
            return ("journal", self.tier[canon], canon)
        if nj.startswith("arxiv") or "预印本" in j:
            return ("preprint", None, None)
        if "公众号" in j or "微信" in j:
            return ("non-journal", None, None)
        return ("unranked", None, None)


def load_rules(cfg):
    lit = K.load_lit_config()
    tiers = {}
    for j in (lit.get("journals") or []):
        if j.get("name") and j.get("tier"):
            tiers[j["name"]] = j["tier"]
    aliases = {}
    ap = (cfg.get("landscape") or {}).get("journal_aliases")
    if ap:
        full = os.path.join(K.VAULT, ap)
        if os.path.isfile(full):
            import yaml
            with open(full, "r", encoding="utf-8") as f:
                aliases = yaml.safe_load(f) or {}
    return JournalRules(tiers, aliases)


# ---------------------------------------------------------------- 读卡 / 聚合

def _as_text(v):
    if isinstance(v, list):
        return "; ".join(str(x).strip() for x in v if str(x).strip())
    return str(v or "").strip()


_INST_SPLIT = re.compile(r"[；;，,、/]")
_INST_BRACKET = re.compile(r"[（(].*?[)）]")


def institution_key(s):
    """机构名归一（粗粒度）：只取第一个分隔符前的机构主体，去掉括号注释。

    用途仅限「粗看哪个单位做得多」。`institution` 原文常是
    「Nankai University，State Key Laboratory…，College of…」这种复合串，
    直接按原文聚合会几乎全为 1，看不出团队。**不要当精确归属使用**。
    """
    s = _as_text(s)
    if not s:
        return ""
    seg = _INST_SPLIT.split(s)[0]
    seg = _INST_BRACKET.sub("", seg).strip()
    return seg or s


def read_card_abs(path):
    """读一张 source 卡：返回 (fm_dict, error)。错误原因用于统计，不静默吞掉。"""
    if not os.path.isfile(path):
        return None, "missing_file"
    text = K.read_text(path)
    raw, _body = K.split_frontmatter(text)
    if not raw.strip():
        return None, "no_frontmatter"
    fm = K.parse_frontmatter(raw)
    if not fm:
        return None, "empty_frontmatter"
    return fm, ""


def read_card(rel_path):
    return read_card_abs(os.path.join(K.VAULT, rel_path))


def _bump(d, key):
    d[key] = d.get(key, 0) + 1


def aggregate(records, rules, top_authors=30):
    """纯函数：records = [{"name","score","fm"}] -> 分面聚合结果（可单测）。"""
    facets = {
        "year": {},
        "journal": {},
        "journal_norm": {},
        "institution": {},
        "source_type": {},
    }
    tier_dist = {}
    author_ctr = collections.Counter()
    team_ctr = collections.Counter()
    unranked = collections.Counter()
    have = collections.Counter()
    years = []

    for rec in records:
        fm = rec.get("fm") or {}
        # year
        y = _as_text(fm.get("year"))
        if y.isdigit():
            _bump(facets["year"], y)
            years.append(int(y))
            have["year"] += 1
        else:
            _bump(facets["year"], "unknown")
        # journal -> tier
        j = _as_text(fm.get("journal"))
        if j:
            _bump(facets["journal"], j)
            have["journal"] += 1
            kind, tier, _canon = rules.classify(j)
            if kind == "journal":
                _bump(tier_dist, tier)
                # 归一后的期刊分布：同一刊的全称/缩写合成一项（原始串见 facets.journal）
                _bump(facets["journal_norm"], rules.display.get(_canon, j))
            elif kind == "unknown":
                _bump(tier_dist, "unknown")
                _bump(facets["journal_norm"], j)
            elif kind == "unranked":
                _bump(tier_dist, "unranked")
                unranked[j] += 1
                _bump(facets["journal_norm"], j)
            else:                      # preprint / non-journal
                _bump(tier_dist, kind)
                _bump(facets["journal_norm"], j)
        else:
            _bump(facets["journal"], "unknown")
            _bump(facets["journal_norm"], "unknown")
            _bump(tier_dist, "unknown")
        # institution
        inst = _as_text(fm.get("institution"))
        if inst:
            _bump(facets["institution"], inst)
            # 公众号/自媒体不是研究团队，不进团队榜；它们仍计入原文分面与覆盖率
            if "公众号" not in inst and "微信" not in inst:
                team_ctr[institution_key(inst)] += 1
            have["institution"] += 1
        else:
            _bump(facets["institution"], "unknown")
            # 不把 unknown 混进团队榜：团队榜是排名视图，不是分区（缺失量看 coverage）
        # source_type
        st = _as_text(fm.get("source_type"))
        if st:
            _bump(facets["source_type"], st)
            have["source_type"] += 1
        else:
            _bump(facets["source_type"], "unknown")
        # authors
        au = fm.get("authors")
        names = au if isinstance(au, list) else ([_as_text(au)] if _as_text(au) else [])
        names = [str(n).strip() for n in names if str(n).strip()]
        if names:
            have["authors"] += 1
            for n in names:
                author_ctr[n] += 1

    total = len(records)
    facets["authors_top"] = [{"name": n, "count": c}
                             for n, c in author_ctr.most_common(top_authors)]
    facets["institution_teams"] = [{"name": n, "count": c}
                                   for n, c in team_ctr.most_common(top_authors)]

    integrity = {
        "total": total,
        "year_sum": sum(facets["year"].values()),
        "journal_sum": sum(facets["journal"].values()),
        "journal_norm_sum": sum(facets["journal_norm"].values()),
        "institution_sum": sum(facets["institution"].values()),
        "source_type_sum": sum(facets["source_type"].values()),
        "tier_sum": sum(tier_dist.values()),
        "coverage": {k: {"n": v, "ratio": round(v / total, 3) if total else 0.0}
                     for k, v in have.items()},
    }
    integrity["all_equal"] = all(
        integrity[k] == total
        for k in ("year_sum", "journal_sum", "journal_norm_sum", "institution_sum",
                  "source_type_sum", "tier_sum"))

    return {
        "facets": facets,
        "tier_distribution": dict(sorted(tier_dist.items())),
        "time_range": [min(years), max(years)] if years else None,
        "unranked_journals": [{"journal": j, "count": c}
                              for j, c in unranked.most_common(20)],
        "integrity": integrity,
    }


