def _embed_arrays():
    """取嵌入矩阵与 name->row 映射（复用 kb_semantic_search 的索引，不另建）。"""
    import kb_semantic_search as S
    emb, emap = S._load_embeddings()
    return emb, emap


def _embed_backend_info():
    p = os.path.join(K.INDEX_DIR, "_embed_backend.json")
    if not os.path.isfile(p):
        return {}
    try:
        with open(p, encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return {}


def _concept_outlinks(names):
    """source 卡 -> 它指向的 concept 页名列表（来自 meta_full 的 out 字段）。"""
    p = os.path.join(K.INDEX_DIR, "meta_full.json")
    with open(p, encoding="utf-8") as f:
        pages = (json.load(f).get("pages") or {})
    out = {}
    for n in names:
        cons = []
        for o in (pages.get(n, {}).get("out") or []):
            if o.startswith("concepts/"):
                cons.append(re.sub(r"\.md$", "", o.split("/", 1)[1]))
        out[n] = cons
    return out


def choose_clusters(vectors, k_range, min_size, seed=0):
    """KMeans + 余弦轮廓系数选 k。返回 (labels, k, silhouette)。

    k 只在「每簇 >= min_size」的候选里挑；全不满足时退化为最大可行 k（并在结果里标注）。
    **纯函数**：不读盘，自检可直接喂合成向量。
    """
    import numpy as np
    from sklearn.cluster import KMeans
    from sklearn.metrics import silhouette_score

    n = len(vectors)
    best = None
    fallback = None
    for k in k_range:
        if k < 2 or k >= n:
            continue
        km = KMeans(n_clusters=k, random_state=seed, n_init=10)
        labels = km.fit_predict(vectors)
        sizes = np.bincount(labels, minlength=k)
        try:
            sil = float(silhouette_score(vectors, labels, metric="cosine"))
        except Exception:
            sil = -1.0
        cand = {"labels": labels, "k": k, "silhouette": sil,
                "min_size": int(sizes.min())}
        if sizes.min() >= min_size and (best is None or sil > best["silhouette"]):
            best = cand
        if fallback is None or sil > fallback["silhouette"]:
            fallback = cand
    chosen = best or fallback
    if chosen is None:
        raise ValueError("样本太少，无法聚类")
    chosen["fallback"] = best is None
    return chosen


def _trend(years):
    ys = [int(y) for y in years if str(y).isdigit()]
    if not ys:
        return {"label": "unknown", "recent_share": None, "span": None}
    recent = sum(1 for y in ys if y >= 2025)
    share = recent / len(ys)
    label = "rising" if share >= 0.7 else ("declining" if share <= 0.2 else "stable")
    return {"label": label, "recent_share": round(share, 2),
            "span": [min(ys), max(ys)]}


def name_clusters(labels, names, concept_map):
    """给每簇起名：取簇内出现最多的 concept（同分优先更「专有」的）。

    返回 {cluster_id: {"name":..., "concepts_top":[(concept,count)...]}}。
    """
    global_freq = collections.Counter()
    for n in names:
        for c in set(concept_map.get(n, [])):
            global_freq[c] += 1
    out = {}
    used = set()
    for cid in sorted(set(int(x) for x in labels)):
        members = [names[i] for i, lab in enumerate(labels) if int(lab) == cid]
        ctr = collections.Counter()
        for m in members:
            for c in set(concept_map.get(m, [])):
                ctr[c] += 1
        ranked = sorted(ctr.items(),
                        key=lambda kv: (-kv[1], global_freq.get(kv[0], 0), kv[0]))
        pick = None
        for con, _cnt in ranked:
            if con not in used:
                pick = con
                break
        if pick is None:
            pick = f"子方向 {cid}"
        used.add(pick)
        out[cid] = {"name": pick,
                    "concepts_top": [{"concept": c, "count": n}
                                     for c, n in ranked[:5]]}
    return out


def concept_groups(records, concept_map, min_size=3, max_groups=10, max_share=0.8,
                   exclude=None):
    """按 concept 出链直接分组（**主口径**）。

    与 KMeans 不同，这里不做「每篇只归一簇」的假设：**方向图谱本就重叠**，
    一篇讲「SEI 界面 + 锂金属」的卡同属两个子方向。覆盖率按「至少进一个组」计。
    过泛的概念（> max_share 的卡都链它）不作为子方向——那通常是方向本身，不是细分。
    """
    total = len(records)
    ctr = collections.Counter()
    for r in records:
        for c in set(concept_map.get(r["name"], [])):
            ctr[c] += 1
    picked = []
    exclude = set(exclude or ())
    for con, cnt in ctr.most_common():
        if con in exclude:
            continue
        if cnt < min_size:
            break
        if total and cnt / total > max_share:
            continue
        picked.append((con, cnt))
        if len(picked) >= max_groups:
            break
    groups, covered = [], set()
    eligible_names = set()
    for r in records:
        if any(ctr[c] >= min_size and (not total or ctr[c] / total <= max_share)
               for c in set(concept_map.get(r["name"], []))):
            eligible_names.add(r["name"])
    for con, _cnt in picked:
        members = [r for r in records if con in set(concept_map.get(r["name"], []))]
        covered.update(r["name"] for r in members)
        ms = sorted(members, key=lambda r: -float(r.get("score") or 0.0))
        groups.append({
            "name": con,
            "kind": "concept-group",
            "source_count": len(members),
            "share": round(len(members) / total, 3) if total else 0.0,
            "trend": _trend([_as_text((r["fm"] or {}).get("year")) for r in members]),
            "key_papers": [{"name": r["name"], "score": round(float(r.get("score") or 0), 3),
                            "year": _as_text((r["fm"] or {}).get("year"))}
                           for r in ms[:5]],
            "members": [r["name"] for r in ms],
        })
    info = {
        "method": "concept-outlink grouping",
        "min_size": min_size, "max_groups": max_groups, "max_share": max_share,
        "groups": len(groups),
        "coverage_selected": round(len(covered) / total, 3) if total else 0.0,
        "coverage_eligible": round(len(eligible_names) / total, 3) if total else 0.0,
        "overlap_allowed": True,
        "note": ("子方向=concept 页；一篇可属多个子方向；过泛概念（>max_share）不作为子方向。"
                 "coverage_selected=上榜 N 个组的覆盖；coverage_eligible=所有合格概念的覆盖"),
    }
    info["eligible_concepts"] = sum(
        1 for c, v in ctr.items()
        if v >= min_size and (not total or v / total <= max_share))
    return groups, info


def add_subdirections(data, records, cfg, k_override=None, seed=0):
    """补 sub_directions（concept 分组，主）+ semantic_clusters（嵌入聚类，辅）。"""
    land = cfg.get("landscape") or {}
    min_size = int(land.get("min_sources_per_subdirection") or 3)
    max_k = int(land.get("max_subdirections") or 10)
    max_share = float(land.get("concept_group_max_share") or 0.8)

    concept_map = _concept_outlinks([r["name"] for r in records])
    anchor = ((data.get("signal") or {}).get("direction_anchor") or {})
    # 方向本身不列为子方向（如查「电解液设计」时，concept 页「电解液设计」是方向而非细分）
    groups, ginfo = concept_groups(records, concept_map, min_size, max_k,
                                   max_share=max_share,
                                   exclude=[anchor["page"]] if anchor.get("page") else None)
    data["sub_directions"] = groups
    data["sub_directions_note"] = (
        "子方向 = source 卡共同指向的 concept 页（>= min_size 篇）；一篇可同时属于多个"
        "子方向（方向图谱本就重叠），因此 source_count 之和会大于候选数。"
        "trend.label 以库内快照为准，须与 recent_share 一起看。")
    data["concept_grouping"] = ginfo

    try:
        sub = _semantic_clusters(records, concept_map, cfg, k_override, seed,
                                 min_size, max_k)
        data["semantic_clusters"] = sub["sub_directions"]
        data["semantic_clusters_note"] = (
            "语义嵌入 KMeans（**辅助视图**）：k 按余弦轮廓系数选。本方向实测轮廓系数"
            "很低（0.05–0.12），说明嵌入空间里子结构不明显；簇名取簇内最多的 concept，"
            "命名冲突时会退到次优概念——仅作参考，不要当权威分区。")
        data["clustering"] = sub["clustering"]
    except Exception as e:      # 嵌入索引缺失/样本过少不应阻断主口径
        data["semantic_clusters"] = []
        data["clustering"] = {"error": str(e)}
    return data


def _semantic_clusters(records, concept_map, cfg, k_override, seed, min_size, max_k):
    import numpy as np
    emb, emap = _embed_arrays()
    if emb is None or not emap:
        raise RuntimeError("嵌入索引缺失：先运行 python tools/kb_semantic_search.py --build")

    kept = [r for r in records if r["name"] in emap]
    missing = [r["name"] for r in records if r["name"] not in emap]
    if len(kept) < max(4, min_size * 2):
        raise RuntimeError(f"可用嵌入样本过少（{len(kept)}），无法聚类")

    vectors = np.asarray([emb[emap[r["name"]]] for r in kept], dtype="float32")
    if k_override:
        k_range = [int(k_override)]
    else:
        k_range = list(range(max(2, min_size), min(max_k, len(kept) // min_size) + 1))

    chosen = choose_clusters(vectors, k_range, min_size, seed=seed)
    labels = [int(x) for x in chosen["labels"]]
    names = [r["name"] for r in kept]
    naming = name_clusters(labels, names, concept_map)

    subs = []
    for cid in sorted(set(labels)):
        members = [r for r, lab in zip(kept, labels) if lab == cid]
        ms = sorted(members, key=lambda r: -float(r.get("score") or 0.0))
        subs.append({
            "name": naming[cid]["name"],
            "source_count": len(members),
            "share": round(len(members) / len(kept), 3),
            "trend": _trend([_as_text((r["fm"] or {}).get("year")) for r in members]),
            "key_papers": [{"name": r["name"], "score": round(float(r.get("score") or 0), 3),
                            "year": _as_text((r["fm"] or {}).get("year"))}
                           for r in ms[:5]],
            "concepts_top": naming[cid]["concepts_top"],
        })
    subs.sort(key=lambda x: -x["source_count"])

    info = _embed_backend_info()
    return {"sub_directions": subs,
            "clustering": {
                "method": "kmeans(cosine silhouette)",
                "k": int(chosen["k"]),
                "k_range": [int(x) for x in k_range],
                "silhouette": round(float(chosen["silhouette"]), 3),
                "min_cluster_size": int(chosen["min_size"]),
                "fallback_no_valid_k": bool(chosen.get("fallback")),
                "seed": seed,
                "embedded": len(kept),
                "missing_embeddings": missing,
                "backend": info.get("backend"),
                "model": info.get("model"),
                "dim": info.get("dim"),
            }}


# ---------------------------------------------------------------- 检索 / 组装

def _load_index():
    """复用 kb_route 的索引加载（与检索层同一份 meta/bm25）。"""
    import kb_route as R
    KS, (meta, bm) = R._meta_and_bm()
    return R, KS, meta, bm


def build(direction, top_k=None, cfg=None, cluster=False, k_override=None):
    cfg = cfg or load_config()
    land = cfg.get("landscape") or {}
    top_k = int(top_k or land.get("candidate_top_k") or DEFAULT_TOP_K)

    R, KS, meta, bm = _load_index()
    rows = R.layer2(direction, top_k, KS, meta, bm)
    l1 = R.layer1(direction, int(land.get("l1_context_k") or 20), KS, meta, bm)

    records, skipped = [], []
    for row in rows:
        fm, err = read_card(row["path"])
        if err:
            skipped.append({"name": row["name"], "path": row["path"], "reason": err})
            continue
        records.append({"name": row["name"], "score": row.get("score", 0.0),
                        "path": row.get("path", ""), "fm": fm})

    rules = load_rules(cfg)
    agg = aggregate(records, rules, int(land.get("top_authors") or 30))

    tops = [float(r.get("score", 0.0)) for r in rows]
    top_score = max(tops) if tops else 0.0
    l1_hits = collections.Counter(str(x.get("type") or "?") for x in l1)

    # 方向锚定：该方向在库内是否有**同名/别名**的 concept/topic 页。
    # 这比 BM25 绝对分可靠——实测「量子纠缠催化反应堆」得 12.9、「电解液设计」只得 2.8，
    # 分数不可跨查询比较（CLAUDE.md：BM25 无分数下限）。
    anchor = None
    for alias, canon in KS.resolve_aliases(direction, meta.get("alias_map", {})):
        if canon == direction.strip() or alias == direction.strip().lower():
            s, _u, _tags, _al, ptype = KS.meta_of(meta, canon)
            anchor = {"page": canon, "type": ptype, "matched_alias": alias}
            break

    srt = sorted(tops, reverse=True)
    score_stats = {
        "top": round(srt[0], 3) if srt else 0.0,
        "p50": round(srt[len(srt) // 2], 3) if srt else 0.0,
        "p10": round(srt[max(0, int(len(srt) * 0.9)) - 1], 3) if srt else 0.0,
    }

    data = {
        "topic_id": slugify(direction),
        "query_direction": direction,
        "generated_at": datetime.date.today().isoformat(),
        "config": {
            "candidate_top_k": top_k,
            "tier_source": "tools/lit_config.yaml",
            "journal_alias_source": land.get("journal_aliases"),
        },
        "kb_coverage": {
            "total_sources": len(records),
            "requested_top_k": top_k,
            "skipped_cards": len(skipped),
            "l1_hits": dict(l1_hits),
            "time_range": agg["time_range"],
            "tier_distribution": agg["tier_distribution"],
        },
        "facets": agg["facets"],
        "facets_note": ("institution 为 frontmatter 原文聚合（可逐条独立复算）；"
                        "institution_teams 只取首个分隔符前的机构主体，仅供粗看团队；"
                        "authors_top 为字面名聚合，同名不同人需人工核对"),
        "unranked_journals": agg["unranked_journals"],
        "integrity": agg["integrity"],
        "signal": {
            "top_score": round(float(top_score), 3),
            "score_stats": score_stats,
            "direction_anchor": anchor,
            "note": ("BM25 分数**不可跨查询比较**（实测无意义查询也可得高分）；"
                     "判断覆盖度请看 direction_anchor（方向是否为库内已命名页）"
                     "与 integrity.coverage 的字段覆盖率，不要只看 top_score"),
        },
        "skipped": skipped,
        "sub_directions": [],
        "sub_directions_note": "P1.2（sci_landscape 聚类）实现；本版只做分面聚合",
    }
    # 候选清单始终落盘：既供 P1.2 聚类，也让分面可被**独立脚本**逐条复算
    # （验收要求「分面合计 == 候选集大小」且能反查，不给清单就无法事后审计）。
    data["candidates"] = [
        {"name": r["name"], "score": r.get("score", 0.0), "path": r.get("path", ""),
         "journal": _as_text((r["fm"] or {}).get("journal")),
         "year": _as_text((r["fm"] or {}).get("year")),
         "institution": _as_text((r["fm"] or {}).get("institution"))}
        for r in records]
    if cluster:
        add_subdirections(data, records, cfg, k_override=k_override)
    return data

def slugify(s):
    s = re.sub(r'[<>:"/\\|?*\s]+', "-", str(s or "").strip())
    return s.strip("-.") or "topic"


def out_path(cfg, direction, out=None):
    if out:
        return os.path.abspath(out)
    topics = (cfg.get("sci") or {}).get("topics_dir") or "projects/sci-assistant/topics"
    return os.path.join(K.VAULT, topics, slugify(direction), "landscape.json")


def write_json(path, data):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    text = json.dumps(data, ensure_ascii=False, indent=2)
    with open(path, "w", encoding="utf-8", newline="\n") as f:
        f.write(text + "\n")
    # 写后复算：JSON 必须能读回且总数字段一致（CLAUDE.md 写盘纪律）
    with open(path, "r", encoding="utf-8") as f:
        back = json.load(f)
    if back["kb_coverage"]["total_sources"] != data["kb_coverage"]["total_sources"]:
        raise SystemExit(f"[!] 写盘复算失败: {path}")
    return path


# ---------------------------------------------------------------- 自检

def _selftest():
    fails = []

    def chk(label, cond, detail=""):
        print(("  ok   " if cond else "  FAIL ") + label +
              (f"   [{detail}]" if detail and not cond else ""))
        if not cond:
            fails.append(label)

    # 用 kb_lib.make_temp_dir：本机 temp 可能不可写（沙箱/受限环境），
    # 该函数会真写探针、逐级回退，并在清理失败时也不否定已完成检查。
    tmp = K.make_temp_dir(prefix="sci_landscape_")
    try:
        files = {
            "good.md": ("---\ncreated: 2020-01-01\ntype: source\njournal: Nature\n"
                        "year: 2024\ninstitution: MIT\nauthors:\n  - Alice\n  - Bob\n"
                        "source_type: Research Article\n---\nbody\n"),
            "alias.md": ("---\njournal: Journal of the American Chemical Society\n"
                         "year: 2023\ninstitution: Stanford\nauthors: [Carol]\n---\nbody\n"),
            "unknown.md": ("---\njournal: Unknown Journal X\ninstitution: \"\"\n---\nbody\n"),
            "preprint.md": "---\njournal: arXiv (cond-mat)\nyear: 2022\n---\nbody\n",
            "nofm.md": "just a body without frontmatter\n",
            "badfm.md": "---\nthis line has no key value\n---\nbody\n",
        }
        paths = {}
        for name, text in files.items():
            p = os.path.join(tmp, name)
            with open(p, "w", encoding="utf-8", newline="\n") as f:
                f.write(text)
            paths[name] = p

        # 1) 读卡
        fm, err = read_card_abs(paths["good.md"])
        chk("读卡：正常卡解析出 year/journal", err == "" and fm.get("year") == "2024")
        fm2, err2 = read_card_abs(paths["nofm.md"])
        chk("读卡：无 frontmatter 被识别（不静默当空卡）", fm2 is None and err2 == "no_frontmatter")
        fm3, err3 = read_card_abs(paths["badfm.md"])
        chk("读卡：坏 frontmatter 被识别", fm3 is None and err3 == "empty_frontmatter")
        fm4, err4 = read_card_abs(os.path.join(tmp, "nope.md"))
        chk("读卡：缺文件", fm4 is None and err4 == "missing_file")

        # 2) 期刊规则：白名单 + 别名 + 负例
        rules = JournalRules({"Nature": "T0", "JACS": "T0"},
                             {"JACS": ["Journal of the American Chemical Society"]})
        chk("期刊：白名单直命中 Nature -> T0", rules.classify("Nature")[:2] == ("journal", "T0"))
        chk("期刊：全称经别名 -> JACS/T0",
            rules.classify("Journal of the American Chemical Society")[:2] == ("journal", "T0"))
        chk("期刊：未知刊不静默给档",
            rules.classify("Unknown Journal X")[0] == "unranked")
        chk("期刊：arXiv 归 preprint 而非期刊",
            rules.classify("arXiv (cond-mat)")[0] == "preprint")
        chk("期刊：公众号归 non-journal",
            rules.classify("微信公众号：材料AI")[0] == "non-journal")
        bad = JournalRules({"Nature": "T0"}, {"NotInWhitelist": ["Some Journal"]})
        chk("期刊：别名目标不在白名单时拒绝生效",
            bad.bad_alias == ["NotInWhitelist"] and bad.classify("Some Journal")[0] == "unranked")

        # 3) 聚合：正例 4 张（另有 2 张应被跳过）
        records = []
        for name in ("good.md", "alias.md", "unknown.md", "preprint.md"):
            fm, err = read_card_abs(paths[name])
            assert err == ""
            records.append({"name": name, "score": 1.0, "fm": fm})
        agg = aggregate(records, rules, top_authors=5)

        chk("聚合：total = 4", agg["integrity"]["total"] == 4)
        chk("聚合：四个分面 + tier 合计都等于 total", agg["integrity"]["all_equal"])
        chk("聚合：年份缺失进 unknown 桶",
            agg["facets"]["year"].get("unknown") == 1 and
            agg["facets"]["year"].get("2024") == 1)
        chk("聚合：tier 分布含 T0/unranked/preprint",
            agg["tier_distribution"].get("T0") == 2 and
            agg["tier_distribution"].get("unranked") == 1 and
            agg["tier_distribution"].get("preprint") == 1)
        chk("聚合：journal_norm 把全称与缩写合成一项",
            agg["facets"]["journal_norm"].get("JACS") == 1 and
            agg["facets"]["journal_norm"].get("Nature") == 1)
        chk("聚合：未排名期刊被列出", agg["unranked_journals"][0]["journal"] == "Unknown Journal X")
        chk("聚合：authors 分面按出现次数",
            agg["facets"]["authors_top"][0]["name"] in ("Alice", "Bob", "Carol"))
        chk("聚合：institution_teams 不含 unknown（缺失量另见 coverage）",
            sum(x["count"] for x in agg["facets"]["institution_teams"]) == 2)
        chk("机构归一：复合串取首个机构主体",
            institution_key("Nankai University，State Key Laboratory，College of X")
            == "Nankai University")
        chk("机构归一：括号注释被去掉",
            institution_key("复旦大学（高分子科学系）") == "复旦大学")
        wechat = aggregate([{"fm": {"institution": "微信公众号：材料AI"}}], rules)
        chk("聚合：公众号不进团队榜",
            wechat["facets"]["institution_teams"] == [] and
            wechat["facets"]["institution"].get("微信公众号：材料AI") == 1)
        chk("聚合：time_range 只取数字年份",
            agg["time_range"] == [2022, 2024])

        # 4) 负例：空记录不崩、不除零
        empty = aggregate([], rules)
        chk("聚合：零记录不崩且 integrity 成立",
            empty["integrity"]["total"] == 0 and empty["integrity"]["all_equal"]
            and empty["time_range"] is None)

        # 5) 聚类与命名（合成向量；不依赖知识库与嵌入索引）
        try:
            import numpy as _np
            pts = _np.array([[1, 0, 0]] * 4 + [[0, 1, 0]] * 4 + [[0, 0, 1]] * 4,
                            dtype="float32")
            chosen = choose_clusters(pts, [2, 3, 4], min_size=2, seed=0)
            chk("聚类：三团数据自动选出 k=3",
                chosen["k"] == 3 and chosen["silhouette"] > 0.5,
                f"k={chosen['k']} sil={chosen['silhouette']:.2f}")
            cnames = [f"p{i}" for i in range(12)]
            cmap = {f"p{i}": (["X"] if i < 4 else ["Y"] if i < 8 else ["Z"])
                    for i in range(12)}
            nm = name_clusters([0] * 4 + [1] * 4 + [2] * 4, cnames, cmap)
            chk("聚类：按簇内 concept 命名", [nm[i]["name"] for i in (0, 1, 2)]
                == ["X", "Y", "Z"])
            chk("聚类：小簇触发退化路径并标注",
                choose_clusters(pts, [2, 3], min_size=5, seed=0)["fallback"] is True)
            chk("趋势：近年占比映射",
                _trend(["2025", "2026", "2025"])["label"] == "rising" and
                _trend(["2019", "2020"])["label"] == "declining")

            # 主口径：concept 分组（重叠允许、过泛概念剔除）
            recs = [{"name": f"q{i}", "score": 1.0, "fm": {"year": "2025"}}
                    for i in range(6)]
            gmap = {"q0": ["A", "B"], "q1": ["A"], "q2": ["A"],
                    "q3": ["B"], "q4": ["C"], "q5": ["C"]}
            gs, ginfo = concept_groups(recs, gmap, min_size=2, max_groups=5)
            chk("分组：按 concept 计数排序命名",
                [g["name"] for g in gs] == ["A", "B", "C"] and
                gs[0]["source_count"] == 3)
            chk("分组：允许重叠（计数之和 > 篇数）",
                sum(g["source_count"] for g in gs) > len(recs))
            chk("分组：上榜组覆盖率 100%", ginfo["coverage_selected"] == 1.0)
            gs2, _ = concept_groups(recs, {"q0": ["ALL"], "q1": ["ALL"], "q2": ["ALL"],
                                           "q3": ["ALL"], "q4": ["ALL"], "q5": ["ALL"]},
                                    min_size=2, max_groups=5, max_share=0.8)
            chk("分组：过泛概念（>max_share）不作为子方向", gs2 == [])
        except ImportError:
            print("  [skip] numpy/sklearn 不可用，跳过聚类自检")
        chk("slug：中文保留、空白转连字符", slugify("电解液 设计") == "电解液-设计")
        chk("slug：非法字符清理", slugify('a/b:c*d') == "a-b-c-d")
    finally:
        K.remove_temp_dir(tmp)

    print(f"SELFTEST {'PASSED' if not fails else 'FAILED'}: "
          f"{len(fails)} failure(s)")
    return 0 if not fails else 1


# ---------------------------------------------------------------- CLI

def main(argv=None):
    ap = argparse.ArgumentParser(
        description="领域景观分析：方向 -> 分面聚合 -> landscape.json（Phase 1a）")
    ap.add_argument("--direction", help="研究方向，如 \"电解液设计\"")
    ap.add_argument("--top-k", type=int, default=None, help="候选 source 卡上限（默认取配置 200）")
    ap.add_argument("--out", default=None, help="输出路径（默认 topics/<slug>/landscape.json）")
    ap.add_argument("--json", action="store_true", help="把结果 JSON 打印到 stdout")
    ap.add_argument("--no-write", action="store_true", help="不写盘（配合 --json 预览）")
    ap.add_argument("--cluster", action="store_true",
                    help="附加 P1.2 子方向聚类（需嵌入索引：kb_semantic_search --build）")
    ap.add_argument("--clusters", type=int, default=None, help="强制簇数（默认按轮廓系数自动选）")
    ap.add_argument("--selftest", action="store_true", help="自检（不依赖知识库索引）")
    args = ap.parse_args(argv)

    if args.selftest:
        return _selftest()
    if not args.direction:
        ap.print_help()
        return 1

    cfg = load_config()
    try:
        data = build(args.direction, args.top_k, cfg, cluster=args.cluster,
                     k_override=args.clusters)
    except SystemExit as e:
        print(f"[!] {e}", file=sys.stderr)
        print("[!] 若索引缺失，先运行: python tools/kb_build_index.py", file=sys.stderr)
        return 2

    if args.json:
        print(json.dumps(data, ensure_ascii=False, indent=2))

    if not args.no_write:
        path = write_json(out_path(cfg, args.direction, args.out), data)
        cov = data["kb_coverage"]
        integ = data["integrity"]
        print(f"[ok] 方向: {args.direction}")
        print(f"     候选 source 卡: {cov['total_sources']} / 请求 {cov['requested_top_k']}"
              f"（跳过 {cov['skipped_cards']}；top_score={data['signal']['top_score']}，"
              f"锚定={data['signal']['direction_anchor']['page'] if data['signal']['direction_anchor'] else '无'}）")
        print(f"     分面合计一致: {integ['all_equal']}"
              f"（year={integ['year_sum']} journal={integ['journal_sum']}"
              f" journal_norm={integ['journal_norm_sum']}"
              f" institution={integ['institution_sum']} tier={integ['tier_sum']}）")
        if data.get("sub_directions"):
            g = data.get("concept_grouping") or {}
            print(f"     子方向(concept 分组): {len(data['sub_directions'])} 个"
                  f"（上榜覆盖 {g.get('coverage_selected')}；"
                  f"全部合格概念覆盖 {g.get('coverage_eligible')}；允许重叠）")
            cl = data.get("clustering") or {}
            if cl.get("k"):
                print(f"     语义簇(辅助): k={cl.get('k')}, "
                      f"silhouette={cl.get('silhouette')}, "
                      f"fallback={cl.get('fallback_no_valid_k')}")
        print(f"     输出: {os.path.relpath(path, K.VAULT)}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
